package app.tsuyu.mobile;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import androidx.core.content.FileProvider;
import org.json.*;
import java.io.*;
import java.util.*;

public class SettingsActivity extends Activity {
    LinearLayout root; EditText name,user,bio,pass,selected,labelTyping,labelOnline,labelLast; Spinner canWrite,lastSeen,photos,about; CheckBox publicPhoto; TextView avatarHint; String avatar="",oldUser="",pendingImportPass=""; int textSize=15;
    @Override protected void onCreate(Bundle b){super.onCreate(b);textSize=getSharedPreferences("ui",0).getInt("textSize",15);build();load();}
    private void build(){root=Tui.root(this);LinearLayout top=Tui.row(this);Button back=Tui.iconButton(this,R.drawable.ic_back);TextView title=Tui.text(this,"Настройки Tsuyu",22,true);top.addView(back,new LinearLayout.LayoutParams(dp(48),dp(52)));top.addView(title,new LinearLayout.LayoutParams(0,dp(52),1));root.addView(top);back.setOnClickListener(v->finish());ScrollView sv=new ScrollView(this);LinearLayout box=Tui.col(this);sv.addView(box);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));avatarHint=Tui.text(this,"Аватар: не выбран",13,false);Button pick=Tui.button(this,"Выбрать аватар");box.addView(avatarHint);box.addView(pick);name=Tui.input(this,"Имя");user=Tui.input(this,"@username");bio=Tui.input(this,"Описание");pass=Tui.input(this,"Новый пароль (если нужно)");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);box.addView(name);box.addView(user);box.addView(bio);box.addView(pass);box.addView(Tui.text(this,"Приватность",18,true));canWrite=spin(new String[]{"all","contacts","selected","nobody"});lastSeen=spin(new String[]{"all","contacts","selected","nobody"});photos=spin(new String[]{"all","contacts","selected","nobody"});about=spin(new String[]{"all","contacts","selected","nobody"});selected=Tui.input(this,"selected @ через запятую");publicPhoto=new CheckBox(this);publicPhoto.setText("Публичная фотография профиля");publicPhoto.setTextColor(Tui.TEXT);box.addView(Tui.text(this,"Кто может писать",13,false));box.addView(canWrite);box.addView(Tui.text(this,"Кто видит last seen",13,false));box.addView(lastSeen);box.addView(Tui.text(this,"Кто видит фото",13,false));box.addView(photos);box.addView(Tui.text(this,"Кто видит bio",13,false));box.addView(about);box.addView(selected);box.addView(publicPhoto);box.addView(Tui.text(this,"Внешний вид и фразы",18,true));Button font=Tui.button(this,"Выбрать шрифт .ttf/.otf");SeekBar size=new SeekBar(this);size.setMax(12);size.setProgress(textSize-12);labelTyping=Tui.input(this,"Фраза: печатает...");labelOnline=Tui.input(this,"Фраза: онлайн");labelLast=Tui.input(this,"Фраза: был(а)");box.addView(font);box.addView(Tui.text(this,"Размер текста",13,false));box.addView(size);box.addView(labelTyping);box.addView(labelOnline);box.addView(labelLast);box.addView(Tui.text(this,"Ключи E2EE",18,true));LinearLayout keys=Tui.row(this);Button rotate=Tui.button(this,"Сменить ключ");Button export=Tui.button(this,"Экспорт ключа");Button imp=Tui.button(this,"Импорт ключа");keys.addView(rotate,new LinearLayout.LayoutParams(0,dp(52),1));keys.addView(export,new LinearLayout.LayoutParams(0,dp(52),1));keys.addView(imp,new LinearLayout.LayoutParams(0,dp(52),1));box.addView(keys);Button save=Tui.button(this,"Сохранить");box.addView(save);pick.setOnClickListener(v->pick("image/*",21));font.setOnClickListener(v->pick("*/*",22));size.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean f){textSize=12+p;}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){getSharedPreferences("ui",0).edit().putInt("textSize",textSize).apply();Tui.toast(SettingsActivity.this,"Размер: "+textSize);}});save.setOnClickListener(v->save());rotate.setOnClickListener(v->rotate());export.setOnClickListener(v->askExport());imp.setOnClickListener(v->askImport());}
    private Spinner spin(String[] vals){Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,vals);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(a);return s;}
    private void load(){Rt.getProfile(Rt.uid(),new Rt.Got(){public void ok(JSONObject p){oldUser=p.optString("username","");name.setText(p.optString("name",""));user.setText(oldUser);bio.setText(p.optString("bio",getSharedPreferences("private",0).getString("bio","") ));avatar=p.optString("avatar","");avatarHint.setText(avatar.isEmpty()?"Аватар: не выбран":"Аватар: выбран");JSONObject pr=p.optJSONObject("privacy");if(pr!=null){sel(canWrite,pr.optString("canWrite","all"));sel(lastSeen,pr.optString("lastSeen","all"));sel(photos,pr.optString("photos","all"));sel(about,pr.optString("about","all"));selected.setText(pr.optString("selected",""));}labelTyping.setText(getSharedPreferences("ui",0).getString("label_typing","печатает..."));labelOnline.setText(getSharedPreferences("ui",0).getString("label_online","онлайн"));labelLast.setText(getSharedPreferences("ui",0).getString("label_lastSeen","был(а) "));}public void fail(String e){}});} 
    private void sel(Spinner s,String v){for(int i=0;i<s.getCount();i++)if(String.valueOf(s.getItemAtPosition(i)).equals(v)){s.setSelection(i);return;}}
    private void save(){String newUser=Rt.cleanUser(user.getText().toString());HashMap<String,Object> m=new HashMap<>();String bioValue=bio.getText().toString();String aboutMode=String.valueOf(about.getSelectedItem());String photoMode=String.valueOf(photos.getSelectedItem());m.put("name",name.getText().toString());m.put("bio","all".equals(aboutMode)?bioValue:"");m.put("avatar",("all".equals(photoMode)||publicPhoto.isChecked())?avatar:"");HashMap<String,Object> p=new HashMap<>();p.put("canWrite",String.valueOf(canWrite.getSelectedItem()));p.put("lastSeen",String.valueOf(lastSeen.getSelectedItem()));p.put("photos",photoMode);p.put("about",aboutMode);p.put("selected",selected.getText().toString());p.put("publicPhoto",publicPhoto.isChecked());m.put("privacy",p);getSharedPreferences("private",0).edit().putString("bio",bioValue).putString("avatar",avatar).apply();getSharedPreferences("ui",0).edit().putString("label_typing",labelTyping.getText().toString()).putString("label_online",labelOnline.getText().toString()).putString("label_lastSeen",labelLast.getText().toString()).putInt("textSize",textSize).apply();Rt.changeUsername(oldUser,newUser,new Rt.Done(){public void ok(){Rt.updateProfile(m,new Rt.Done(){public void ok(){oldUser=newUser;updatePass();Tui.toast(SettingsActivity.this,"Сохранено");}public void fail(String e){Tui.toast(SettingsActivity.this,e);}});}public void fail(String e){Tui.toast(SettingsActivity.this,e);}});} 
    private void updatePass(){String p=pass.getText().toString();if(p.length()>=6&&TsuyuApp.app().auth.getCurrentUser()!=null)TsuyuApp.app().auth.getCurrentUser().updatePassword(p).addOnFailureListener(e->Tui.toast(this,"Пароль: "+e.getMessage()));}
    private void rotate(){TsuyuApp.app().crypto.rotate();HashMap<String,Object> m=new HashMap<>();m.put("publicKey",TsuyuApp.app().crypto.publicKey());m.put("keyId",TsuyuApp.app().crypto.keyId());m.put("keyRing",TsuyuApp.app().crypto.publicRing().toString());Rt.updateProfile(m,new Rt.Done(){public void ok(){Tui.toast(SettingsActivity.this,"Новый ключ опубликован");}public void fail(String e){Tui.toast(SettingsActivity.this,e);}});} 
    private void askExport(){EditText e=Tui.input(this,"Пароль для архива ключа");e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);new AlertDialog.Builder(this).setTitle("Экспорт ключа").setMessage("Приватный ключ уйдёт только в зашифрованный файл.").setView(e).setPositiveButton("Экспорт",(d,w)->exportKey(e.getText().toString())).setNegativeButton("Отмена",null).show();}
    private void exportKey(String pw){try{if(pw.length()<6){Tui.toast(this,"Пароль минимум 6 символов");return;}String blob=TsuyuApp.app().crypto.exportEncrypted(pw);File dir=new File(getExternalFilesDir(null),"keys");dir.mkdirs();File f=new File(dir,"Tsuyu-key-"+System.currentTimeMillis()+".tsuyukey");try(FileOutputStream os=new FileOutputStream(f)){os.write(blob.getBytes("UTF-8"));}Uri u=FileProvider.getUriForFile(this,"app.tsuyu.mobile.fileprovider",f);Intent share=new Intent(Intent.ACTION_SEND).setType("application/octet-stream").putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(share,"Экспорт ключа Tsuyu"));}catch(Exception e){Tui.toast(this,e.getMessage());}}
    private void askImport(){EditText e=Tui.input(this,"Пароль от архива ключа");e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);new AlertDialog.Builder(this).setTitle("Импорт ключа").setView(e).setPositiveButton("Открыть файл",(d,w)->{pendingImportPass=e.getText().toString();pick("*/*",23);}).setNegativeButton("Отмена",null).show();}
    private void pick(String type,int req){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(type);startActivityForResult(i,req);} 
    @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null||d.getData()==null)return;Uri u=d.getData();if(r==21){TsuyuApp.bg(()->{try{MediaTools.Pack p=MediaTools.image(this,u);avatar=p.thumb.isEmpty()?p.base64:p.thumb;TsuyuApp.ui(()->avatarHint.setText("Аватар: выбран"));}catch(Exception e){TsuyuApp.ui(()->Tui.toast(this,e.getMessage()));}});}else if(r==22){copyFont(u);}else if(r==23){importKey(u);}}
    private void copyFont(Uri u){try(InputStream in=getContentResolver().openInputStream(u);FileOutputStream out=new FileOutputStream(new File(getFilesDir(),"tsuyu-font.ttf"))){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);Tui.toast(this,"Шрифт установлен");}catch(Exception e){Tui.toast(this,e.getMessage());}}
    private void importKey(Uri u){try(InputStream in=getContentResolver().openInputStream(u);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);TsuyuApp.app().crypto.importEncrypted(out.toString("UTF-8"),pendingImportPass);HashMap<String,Object> m=new HashMap<>();m.put("publicKey",TsuyuApp.app().crypto.publicKey());m.put("keyId",TsuyuApp.app().crypto.keyId());m.put("keyRing",TsuyuApp.app().crypto.publicRing().toString());Rt.updateProfile(m,new Rt.Done(){public void ok(){Tui.toast(SettingsActivity.this,"Ключ импортирован");}public void fail(String e){Tui.toast(SettingsActivity.this,e);}});}catch(Exception e){Tui.toast(this,e.getMessage());}}
    int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);} 
}
